function angle_ranking_alpha_compare
% angle_ranking_alpha_compare
% MATLAB R2015-compatible helper that combines angle-ranking data across
% alpha values (and, if present, across different source types).
%
% Preferred input:
%   - angle_ranking_*_vs_*.csv files generated by penelope_report_dose_analysis
%
% Fallback input:
%   - *_Dose.xlsx / *_Dose.xls files with the standard "Dose" worksheet
%
% Outputs:
%   - combined long-form CSV
%   - combined wide/matrix CSV
%   - series-summary CSV
%   - raw ratio comparison plots ranked by selected reference alpha
%   - target-dose line plots using ranked and pair-order views

close all;
clc;
disp(['Running angle_ranking_alpha_compare from: ' mfilename('fullpath')]);

%% ---------------- USER PARAMETERS ----------------
rootDir = fileparts(mfilename('fullpath'));
if isempty(rootDir) || ~exist(rootDir, 'dir')
    rootDir = pwd;
end

% 'auto' prefers existing ranking CSVs. Use 'xlsx' to force workbook mode.
inputMode = 'auto';   % 'auto' | 'csv' | 'xlsx'

% Normalization applied independently to each alpha/source series.
% 'max' : 100 * value / max(series)
% 'sum' : 100 * value / sum(series)
% 'none': keep raw CompareTarget_pct values
normalizationMode = 'max';   % 'max' | 'sum' | 'none'
normalizedScale = 100;
targetDosePlotLogScale = false;
rawRatioReferenceAlphaAll = 2.86;
rawRatioSubsetReferenceAlpha = 1.0;
rawRatioSubsetAlphas = [0.49 1.0];

% Workbook mode only. Leave empty to ask interactively if needed.
compareBodyName = '';
targetBodyName = '';

% Leave empty to save next to the selected data root.
outDir = '';

grau = char(176);

[csvFiles, workbookFiles] = discover_input_files_r2015(rootDir);
if isempty(csvFiles) && isempty(workbookFiles)
    chosenRoot = uigetdir(rootDir, 'Select folder with angle-ranking CSVs or Dose workbooks');
    if isequal(chosenRoot, 0)
        disp('No input folder selected. Exiting angle_ranking_alpha_compare.');
        return;
    end
    rootDir = chosenRoot;
    [csvFiles, workbookFiles] = discover_input_files_r2015(rootDir);
end

if isempty(csvFiles) && isempty(workbookFiles)
    disp('No angle-ranking CSV files or Dose workbooks were found.');
    return;
end

if isempty(outDir)
    outDir = rootDir;
end
if ~exist(outDir, 'dir')
    mkdir(outDir);
end

modeToUse = resolve_input_mode_r2015(inputMode, csvFiles, workbookFiles);
if isempty(modeToUse)
    disp('No usable input mode is available. Exiting.');
    return;
end

groups = struct('token', {}, 'compareLabel', {}, 'targetLabel', {}, 'rows', {});
if strcmp(modeToUse, 'csv')
    groups = load_ranking_groups_from_csv_r2015(csvFiles);
else
    if isempty(compareBodyName) || isempty(targetBodyName)
        defaults = {'Olho direito', 'Tumor olho dto'};
        if ~isempty(compareBodyName)
            defaults{1} = compareBodyName;
        end
        if ~isempty(targetBodyName)
            defaults{2} = targetBodyName;
        end
        answers = inputdlg({'Compare BODY label', 'Target BODY label'}, ...
            'Angle ranking from Dose workbook', 1, defaults);
        if isempty(answers)
            disp('Workbook compare/target labels were not provided. Exiting.');
            return;
        end
        compareBodyName = strtrim(answers{1});
        targetBodyName = strtrim(answers{2});
    end
    groups = load_ranking_groups_from_workbooks_r2015(workbookFiles, compareBodyName, targetBodyName);
end

if isempty(groups)
    disp('No usable angle-ranking rows were loaded.');
    return;
end

processedGroups = 0;
for g = 1:numel(groups)
    try
        process_ranking_group_r2015(groups(g), outDir, normalizationMode, normalizedScale, targetDosePlotLogScale, grau, ...
            rawRatioReferenceAlphaAll, rawRatioSubsetReferenceAlpha, rawRatioSubsetAlphas);
        processedGroups = processedGroups + 1;
        disp(['Processed combined ranking: ' groups(g).compareLabel ' vs ' groups(g).targetLabel]);
    catch ME
        disp(['Failed combined ranking ', groups(g).token, ': ' ME.message]);
    end
end

disp(['Processed ranking groups: ' num2str(processedGroups)]);
end

function [csvFiles, workbookFiles] = discover_input_files_r2015(rootDir)
csvFiles = collect_matching_files_recursive_r2015(rootDir, 'csv');
workbookFiles = collect_matching_files_recursive_r2015(rootDir, 'xlsx');
end

function files = collect_matching_files_recursive_r2015(rootDir, modeName)
files = {};
if nargin < 2 || isempty(rootDir) || ~exist(rootDir, 'dir')
    return;
end

listing = dir(rootDir);
for i = 1:numel(listing)
    item = listing(i);
    itemName = item.name;
    if strcmp(itemName, '.') || strcmp(itemName, '..')
        continue;
    end
    fullPath = fullfile(rootDir, itemName);
    if item.isdir
        nested = collect_matching_files_recursive_r2015(fullPath, modeName);
        if ~isempty(nested)
            files = [files; nested]; %#ok<AGROW>
        end
        continue;
    end

    switch lower(modeName)
        case 'csv'
            if ~isempty(regexp(itemName, '^angle_ranking_.+_vs_.+\.csv$', 'once'))
                files{end + 1, 1} = fullPath; %#ok<AGROW>
            end
        case 'xlsx'
            lowerName = lower(itemName);
            if ~isempty(regexp(lowerName, '_dose\.xlsx$', 'once')) || ~isempty(regexp(lowerName, '_dose\.xls$', 'once'))
                files{end + 1, 1} = fullPath; %#ok<AGROW>
            end
    end
end
end

function modeToUse = resolve_input_mode_r2015(inputMode, csvFiles, workbookFiles)
modeToUse = '';
requested = lower(strtrim(inputMode));
switch requested
    case 'csv'
        if ~isempty(csvFiles)
            modeToUse = 'csv';
        end
    case 'xlsx'
        if ~isempty(workbookFiles)
            modeToUse = 'xlsx';
        end
    otherwise
        if ~isempty(csvFiles)
            modeToUse = 'csv';
        elseif ~isempty(workbookFiles)
            modeToUse = 'xlsx';
        end
end
end

function groups = load_ranking_groups_from_csv_r2015(csvFiles)
groups = struct('token', {}, 'compareLabel', {}, 'targetLabel', {}, 'rows', {});
for i = 1:numel(csvFiles)
    [compareToken, targetToken] = parse_ranking_group_tokens_r2015(csvFiles{i});
    if isempty(compareToken) || isempty(targetToken)
        continue;
    end
    token = [compareToken '_vs_' targetToken];
    T = load_ranking_csv_r2015(csvFiles{i});
    if height(T) == 0
        continue;
    end
    idx = find(strcmp({groups.token}, token), 1);
    if isempty(idx)
        idx = numel(groups) + 1;
        groups(idx).token = token; %#ok<AGROW>
        groups(idx).compareLabel = display_label_from_token_r2015(compareToken); %#ok<AGROW>
        groups(idx).targetLabel = display_label_from_token_r2015(targetToken); %#ok<AGROW>
        groups(idx).rows = T; %#ok<AGROW>
    else
        groups(idx).rows = [groups(idx).rows; T];
    end
end
end

function groups = load_ranking_groups_from_workbooks_r2015(workbookFiles, compareBodyName, targetBodyName)
groups = struct('token', {}, 'compareLabel', {}, 'targetLabel', {}, 'rows', {});
compareLabel = strtrim(compareBodyName);
targetLabel = strtrim(targetBodyName);
if isempty(compareLabel) || isempty(targetLabel)
    return;
end

token = [safe_label_file_token_r2015(compareLabel) '_vs_' safe_label_file_token_r2015(targetLabel)];
rows = table();
for i = 1:numel(workbookFiles)
    T = build_ranking_table_from_workbook_r2015(workbookFiles{i}, compareLabel, targetLabel);
    if height(T) == 0
        continue;
    end
    if isempty(rows)
        rows = T;
    else
        rows = [rows; T];
    end
end

if isempty(rows)
    return;
end
groups(1).token = token;
groups(1).compareLabel = compareLabel;
groups(1).targetLabel = targetLabel;
groups(1).rows = rows;
end

function process_ranking_group_r2015(group, outDir, normalizationMode, normalizedScale, targetDosePlotLogScale, grau, rawRatioReferenceAlphaAll, rawRatioSubsetReferenceAlpha, rawRatioSubsetAlphas)
T = group.rows;
if isempty(T) || height(T) == 0
    return;
end

validMask = isfinite(T.Alpha) & isfinite(T.THETA) & isfinite(T.PHI) & isfinite(T.CompareTarget_pct);
T = T(validMask, :);
if isempty(T) || height(T) == 0
    error('No valid rows remained after filtering THETA/PHI/Alpha/ratio values.');
end

T.SourceType = fill_empty_labels_r2015(T.SourceType, 'Unknown source');

seriesMeta = build_series_metadata_r2015(T.SourceType, T.Alpha, grau);
pairMeta = build_pair_metadata_r2015(T.THETA, T.PHI);
if isempty(seriesMeta.keys) || isempty(pairMeta.labels)
    error('Could not build series or angle-pair metadata.');
end

[rawMatrix, rawErrMatrix, targetDoseMatrix, compareDoseMatrix, countMatrix] = ...
    build_series_matrices_r2015(T, seriesMeta, pairMeta);

[rawAvailableCount, rawMean, rawMax] = compute_target_statistics_r2015(rawMatrix); %#ok<ASGLU>
[normMatrix, normErrMatrix, seriesDenominator] = ...
    normalize_series_matrix_r2015(rawMatrix, rawErrMatrix, normalizationMode, normalizedScale);

[availableCount, normMean, normRange, normStd] = compute_pair_statistics_r2015(normMatrix);
pairOrder = sort_pair_order_r2015(normRange, normMean, pairMeta.theta, pairMeta.phi);

pairMeta.theta = pairMeta.theta(pairOrder);
pairMeta.phi = pairMeta.phi(pairOrder);
pairMeta.labels = pairMeta.labels(pairOrder);
pairMeta.keys = pairMeta.keys(pairOrder);
rawMatrix = rawMatrix(pairOrder, :);
rawErrMatrix = rawErrMatrix(pairOrder, :);
targetDoseMatrix = targetDoseMatrix(pairOrder, :);
compareDoseMatrix = compareDoseMatrix(pairOrder, :);
countMatrix = countMatrix(pairOrder, :);
normMatrix = normMatrix(pairOrder, :);
normErrMatrix = normErrMatrix(pairOrder, :);
availableCount = availableCount(pairOrder);
normMean = normMean(pairOrder);
normRange = normRange(pairOrder);
normStd = normStd(pairOrder);

baseName = ['combined_angle_ranking_' group.token];

longTable = build_long_output_table_r2015(group, pairMeta, seriesMeta, rawMatrix, rawErrMatrix, ...
    targetDoseMatrix, compareDoseMatrix, normMatrix, normErrMatrix, countMatrix, seriesDenominator);
matrixTable = build_matrix_output_table_r2015(pairMeta, seriesMeta, rawMatrix, rawErrMatrix, ...
    targetDoseMatrix, compareDoseMatrix, normMatrix, normErrMatrix, countMatrix, ...
    availableCount, normMean, normRange, normStd);
summaryTable = build_series_summary_table_r2015(seriesMeta, rawMatrix, countMatrix, seriesDenominator);

writetable(longTable, fullfile(outDir, [baseName '_long.csv']));
writetable(matrixTable, fullfile(outDir, [baseName '_matrix.csv']));
writetable(summaryTable, fullfile(outDir, [baseName '_series_summary.csv']));

[targetAvailableCount, targetMean, targetMax] = compute_target_statistics_r2015(targetDoseMatrix);
targetPairOrder = sort_target_pair_order_r2015(targetMean, targetMax, pairMeta.theta, pairMeta.phi);
targetPairMeta = pairMeta;
targetPairMeta.theta = targetPairMeta.theta(targetPairOrder);
targetPairMeta.phi = targetPairMeta.phi(targetPairOrder);
targetPairMeta.labels = targetPairMeta.labels(targetPairOrder);
targetPairMeta.keys = targetPairMeta.keys(targetPairOrder);
targetDoseRankMatrix = targetDoseMatrix(targetPairOrder, :);
targetCountRankMatrix = countMatrix(targetPairOrder, :);
targetAvailableCount = targetAvailableCount(targetPairOrder);
targetMean = targetMean(targetPairOrder);
targetMax = targetMax(targetPairOrder);
targetRankTable = build_target_rank_table_r2015(targetPairMeta, seriesMeta, targetDoseRankMatrix, targetCountRankMatrix, targetAvailableCount, targetMean, targetMax);
writetable(targetRankTable, fullfile(outDir, [baseName '_target_dose_ranked.csv']));

refAllIdx = find_reference_series_index_by_alpha_r2015(seriesMeta, rawRatioReferenceAlphaAll);
if isempty(refAllIdx)
    refAllIdx = find_first_finite_series_index_r2015(rawMatrix);
    if ~isempty(refAllIdx)
        disp(['Requested reference alpha ', num2str(rawRatioReferenceAlphaAll), ' was not found for ', group.token, '. Using ', seriesMeta.labels{refAllIdx}, ' instead.']);
    end
end

subsetSeriesIdx = find_series_indices_by_alpha_r2015(seriesMeta, rawRatioSubsetAlphas);
subsetRefIdx = find_reference_series_index_by_alpha_r2015(seriesMeta, rawRatioSubsetReferenceAlpha);
plotTitles = resolve_plot_titles_r2015(group, seriesMeta, refAllIdx, subsetRefIdx, rawRatioSubsetAlphas, grau);

ratioOrderAll = [];
ratioAllPairMeta = pairMeta;
if ~isempty(refAllIdx)
    ratioOrderAll = sort_pair_order_by_reference_alpha_r2015(rawMatrix, refAllIdx, rawMean, pairMeta.theta, pairMeta.phi);
    ratioAllPairMeta = reorder_pair_metadata_r2015(pairMeta, ratioOrderAll);
    rawMatrixAllOrdered = rawMatrix(ratioOrderAll, :);
    rawErrMatrixAllOrdered = rawErrMatrix(ratioOrderAll, :);

    try
        plot_raw_ratio_horizontal_dots_r2015(group, ratioAllPairMeta.labels, seriesMeta.labels, rawMatrixAllOrdered, rawErrMatrixAllOrdered, ...
            1:numel(seriesMeta.labels), outDir, [baseName '_raw_ratio_ref_' alpha_token_r2015(seriesMeta.alphas(refAllIdx))], plotTitles.ratioAllTitle);
    catch ME
        error('All-alpha raw ratio plot failed: %s', ME.message);
    end
else
    disp(['No finite raw-ratio series were available for ', group.token, '. Skipping all-series raw ratio plot.']);
end

if numel(subsetSeriesIdx) >= 2 && ~isempty(subsetRefIdx)
    ratioOrderSubset = sort_pair_order_by_reference_alpha_r2015(rawMatrix, subsetRefIdx, rawMean, pairMeta.theta, pairMeta.phi);
    ratioSubsetPairMeta = reorder_pair_metadata_r2015(pairMeta, ratioOrderSubset);
    rawMatrixSubsetOrdered = rawMatrix(ratioOrderSubset, :);
    rawErrMatrixSubsetOrdered = rawErrMatrix(ratioOrderSubset, :);

    try
        plot_raw_ratio_horizontal_dots_r2015(group, ratioSubsetPairMeta.labels, seriesMeta.labels, rawMatrixSubsetOrdered, rawErrMatrixSubsetOrdered, ...
            subsetSeriesIdx, outDir, [baseName '_raw_ratio_subset_ref_' alpha_token_r2015(seriesMeta.alphas(subsetRefIdx))], plotTitles.ratioSubsetTitle);
    catch ME
        error('Subset raw ratio plot failed: %s', ME.message);
    end
else
    disp(['Skipping subset raw-ratio plot for ', group.token, ' because alpha 1 and alpha 0.49 were not both available.']);
end

try
    plot_target_dose_ranked_lines_r2015(group, targetPairMeta.labels, seriesMeta.labels, targetDoseRankMatrix, targetDosePlotLogScale, outDir, ...
        [baseName '_target_dose_ranked_desc'], plotTitles.doseRankedTitle, 'Theta/Phi pair');
catch ME
    error('Target-dose descending plot failed: %s', ME.message);
end

if ~isempty(ratioOrderAll)
    targetDoseRatioOrdered = targetDoseMatrix(ratioOrderAll, :);
    try
        plot_target_dose_ranked_lines_r2015(group, ratioAllPairMeta.labels, seriesMeta.labels, targetDoseRatioOrdered, targetDosePlotLogScale, outDir, ...
            [baseName '_target_dose_ratio_order_ref_' alpha_token_r2015(seriesMeta.alphas(refAllIdx))], plotTitles.doseRatioOrderTitle, 'Theta/Phi pair');
    catch ME
        error('Target-dose ratio-order plot failed: %s', ME.message);
    end
end

try
    plot_ratio_vs_target_dose_scatter_r2015(group, seriesMeta, rawMatrix, targetDoseMatrix, outDir, [baseName '_ratio_vs_target_dose_scatter'], plotTitles.scatterTitle);
catch ME
    error('Ratio-vs-dose scatter plot failed: %s', ME.message);
end

screeningTable = build_screening_table_r2015(pairMeta, seriesMeta, rawMatrix, targetDoseMatrix, ratioOrderAll, targetPairOrder, subsetSeriesIdx, subsetRefIdx);
writetable(screeningTable, fullfile(outDir, [baseName '_screening_table.csv']));
end

function T = load_ranking_csv_r2015(csvPath)
T = table();
try
    rawTable = readtable(csvPath, 'Delimiter', ',');
catch
    rawTable = readtable(csvPath);
end
if isempty(rawTable) || height(rawTable) == 0
    return;
end

caseVar = find_table_var_name_r2015(rawTable, {'Case'});
sourceVar = find_optional_table_var_name_r2015(rawTable, {'SourceType', 'Source_Type', 'Source'});
caseIdVar = find_optional_table_var_name_r2015(rawTable, {'CaseID', 'Case_ID'});
alphaVar = find_table_var_name_r2015(rawTable, {'Alpha'});
thetaVar = find_table_var_name_r2015(rawTable, {'THETA', 'Theta'});
phiVar = find_table_var_name_r2015(rawTable, {'PHI', 'Phi'});
targetDoseVar = find_optional_table_var_name_r2015(rawTable, {'TargetDose_eVg'});
dTargetDoseVar = find_optional_table_var_name_r2015(rawTable, {'dTargetDose_eVg'});
compareDoseVar = find_optional_table_var_name_r2015(rawTable, {'CompareDose_eVg'});
dCompareDoseVar = find_optional_table_var_name_r2015(rawTable, {'dCompareDose_eVg'});
ratioVar = find_table_var_name_r2015(rawTable, {'CompareTarget_pct'});
dRatioVar = find_optional_table_var_name_r2015(rawTable, {'dCompareTarget_pct'});

caseNames = table_column_to_strings_r2015(rawTable, caseVar);
sourceTypes = table_column_to_strings_r2015(rawTable, sourceVar);
sourceTypes = fill_empty_labels_r2015(sourceTypes, 'Unknown source');
for i = 1:numel(sourceTypes)
    sourceTypes{i} = normalize_source_type_label_r2015(sourceTypes{i});
end

T = table( ...
    caseNames, ...
    sourceTypes, ...
    table_column_to_numeric_r2015(rawTable, caseIdVar), ...
    table_column_to_numeric_r2015(rawTable, alphaVar), ...
    table_column_to_numeric_r2015(rawTable, thetaVar), ...
    table_column_to_numeric_r2015(rawTable, phiVar), ...
    table_column_to_numeric_r2015(rawTable, targetDoseVar), ...
    table_column_to_numeric_r2015(rawTable, dTargetDoseVar), ...
    table_column_to_numeric_r2015(rawTable, compareDoseVar), ...
    table_column_to_numeric_r2015(rawTable, dCompareDoseVar), ...
    table_column_to_numeric_r2015(rawTable, ratioVar), ...
    table_column_to_numeric_r2015(rawTable, dRatioVar), ...
    repmat({csvPath}, height(rawTable), 1), ...
    'VariableNames', { ...
        'Case', 'SourceType', 'CaseID', 'Alpha', 'THETA', 'PHI', ...
        'TargetDose_eVg', 'dTargetDose_eVg', 'CompareDose_eVg', 'dCompareDose_eVg', ...
        'CompareTarget_pct', 'dCompareTarget_pct', 'InputFile' ...
    });
end

function T = build_ranking_table_from_workbook_r2015(excelPath, compareName, targetName)
doseData = load_dose_sheet_r2015(excelPath);
T = table();
if isempty(doseData.case_names)
    return;
end

n = numel(doseData.case_names);
THETA = nan(n, 1);
PHI = nan(n, 1);
ALPHA = nan(n, 1);
CASEID = nan(n, 1);
for i = 1:n
    c = doseData.case_names{i};
    tok = regexp(c, 'SCONE-([\-0-9\.]+)_([\-0-9\.]+)_([\-0-9\.]+)', 'tokens', 'once');
    if ~isempty(tok)
        THETA(i) = str2double(tok{1});
        PHI(i) = str2double(tok{2});
        ALPHA(i) = str2double(tok{3});
    end
    tok2 = regexp(c, 'case(\d+)', 'tokens', 'once');
    if ~isempty(tok2)
        CASEID(i) = str2double(tok2{1});
    end
end

validMask = ~isnan(ALPHA);
caseNames = doseData.case_names(validMask);
sourceTypes = doseData.source_types(validMask);
sourceTypes = fill_empty_labels_r2015(sourceTypes, 'Unknown source');
componentNames = doseData.component_names(validMask);
doseEvg = doseData.dose_evg(validMask);
dDoseEvg = doseData.ddose_evg(validMask);
THETA = THETA(validMask);
PHI = PHI(validMask);
ALPHA = ALPHA(validMask);
CASEID = CASEID(validMask);

cases = unique(caseNames);
rankCase = {};
rankSourceType = {};
rankCaseID = [];
rankAlpha = [];
rankTheta = [];
rankPhi = [];
rankTargetDose = [];
rankdTargetDose = [];
rankCompareDose = [];
rankdCompareDose = [];
rankComparePct = [];
rankdComparePct = [];
rankInputFile = {};
rowCount = 0;

for i = 1:numel(cases)
    caseMask = strcmp(caseNames, cases{i});
    caseRows = find(caseMask);
    if isempty(caseRows)
        continue;
    end

    localComponents = componentNames(caseRows);
    targetLocalMask = build_component_match_mask_r2015(localComponents, {targetName});
    compareLocalMask = build_component_match_mask_r2015(localComponents, {compareName});
    targetLocalIdx = find(targetLocalMask, 1, 'first');
    compareLocalIdx = find(compareLocalMask, 1, 'first');
    if isempty(targetLocalIdx) || isempty(compareLocalIdx)
        continue;
    end

    targetIdx = caseRows(targetLocalIdx);
    compareIdx = caseRows(compareLocalIdx);
    targetDose = doseEvg(targetIdx);
    dTargetDose = dDoseEvg(targetIdx);
    compareDose = doseEvg(compareIdx);
    dCompareDose = dDoseEvg(compareIdx);
    [ratioPct, dRatioPct] = safe_ratio_pct_r2015(compareDose, dCompareDose, targetDose, dTargetDose);
    if ~isfinite(ratioPct)
        continue;
    end

    rowCount = rowCount + 1;
    rankCase{rowCount, 1} = cases{i}; %#ok<AGROW>
    rankSourceType{rowCount, 1} = normalize_source_type_label_r2015(sourceTypes{targetIdx}); %#ok<AGROW>
    rankCaseID(rowCount, 1) = CASEID(targetIdx); %#ok<AGROW>
    rankAlpha(rowCount, 1) = ALPHA(targetIdx); %#ok<AGROW>
    rankTheta(rowCount, 1) = THETA(targetIdx); %#ok<AGROW>
    rankPhi(rowCount, 1) = PHI(targetIdx); %#ok<AGROW>
    rankTargetDose(rowCount, 1) = targetDose; %#ok<AGROW>
    rankdTargetDose(rowCount, 1) = dTargetDose; %#ok<AGROW>
    rankCompareDose(rowCount, 1) = compareDose; %#ok<AGROW>
    rankdCompareDose(rowCount, 1) = dCompareDose; %#ok<AGROW>
    rankComparePct(rowCount, 1) = ratioPct; %#ok<AGROW>
    rankdComparePct(rowCount, 1) = dRatioPct; %#ok<AGROW>
    rankInputFile{rowCount, 1} = excelPath; %#ok<AGROW>
end

if rowCount == 0
    return;
end

T = table( ...
    rankCase, rankSourceType, rankCaseID, rankAlpha, rankTheta, rankPhi, ...
    rankTargetDose, rankdTargetDose, rankCompareDose, rankdCompareDose, rankComparePct, rankdComparePct, rankInputFile, ...
    'VariableNames', { ...
        'Case', 'SourceType', 'CaseID', 'Alpha', 'THETA', 'PHI', ...
        'TargetDose_eVg', 'dTargetDose_eVg', 'CompareDose_eVg', 'dCompareDose_eVg', ...
        'CompareTarget_pct', 'dCompareTarget_pct', 'InputFile' ...
    });
end

function seriesMeta = build_series_metadata_r2015(sourceTypes, alphaValues, grau)
seriesMeta = struct();
seriesMeta.keys = {};
seriesMeta.labels = {};
seriesMeta.tokens = {};
seriesMeta.sourceTypes = {};
seriesMeta.alphas = [];

sourceTypes = fill_empty_labels_r2015(sourceTypes, 'Unknown source');
for i = 1:numel(sourceTypes)
    sourceTypes{i} = normalize_source_type_label_r2015(sourceTypes{i});
end
uniqueSources = unique(sourceTypes);
showSourceInLegend = numel(uniqueSources) > 1;

for i = 1:numel(alphaValues)
    currentSource = sourceTypes{i};
    currentAlpha = alphaValues(i);
    currentKey = build_series_key_r2015(currentSource, currentAlpha);
    if isempty(find(strcmp(seriesMeta.keys, currentKey), 1))
        seriesMeta.keys{end + 1, 1} = currentKey; %#ok<AGROW>
        seriesMeta.sourceTypes{end + 1, 1} = currentSource; %#ok<AGROW>
        seriesMeta.alphas(end + 1, 1) = currentAlpha; %#ok<AGROW>
        if showSourceInLegend
            seriesMeta.labels{end + 1, 1} = sprintf('%s | alpha = %.4g%c', display_source_type_r2015(currentSource), currentAlpha, grau); %#ok<AGROW>
            seriesMeta.tokens{end + 1, 1} = [safe_file_token_r2015(currentSource) '_alpha_' alpha_token_r2015(currentAlpha)]; %#ok<AGROW>
        else
            seriesMeta.labels{end + 1, 1} = sprintf('alpha = %.4g%c', currentAlpha, grau); %#ok<AGROW>
            seriesMeta.tokens{end + 1, 1} = ['alpha_' alpha_token_r2015(currentAlpha)]; %#ok<AGROW>
        end
    end
end

seriesMeta = sort_series_metadata_r2015(seriesMeta);
end

function seriesMeta = sort_series_metadata_r2015(seriesMeta)
if isempty(seriesMeta.keys)
    return;
end

sortKeys = seriesMeta.tokens;
T = table(sortKeys, seriesMeta.labels, seriesMeta.tokens, seriesMeta.sourceTypes, seriesMeta.alphas, seriesMeta.keys, ...
    'VariableNames', {'SortKey', 'Label', 'Token', 'SourceType', 'Alpha', 'Key'});
T = sortrows(T, {'SortKey'});

seriesMeta.keys = T.Key;
seriesMeta.labels = T.Label;
seriesMeta.tokens = T.Token;
seriesMeta.sourceTypes = T.SourceType;
seriesMeta.alphas = T.Alpha;
end

function pairMeta = build_pair_metadata_r2015(thetaValues, phiValues)
pairMeta = struct();
pairMeta.keys = {};
pairMeta.labels = {};
pairMeta.theta = [];
pairMeta.phi = [];

for i = 1:numel(thetaValues)
    currentTheta = thetaValues(i);
    currentPhi = phiValues(i);
    currentKey = build_pair_key_r2015(currentTheta, currentPhi);
    if isempty(find(strcmp(pairMeta.keys, currentKey), 1))
        pairMeta.keys{end + 1, 1} = currentKey; %#ok<AGROW>
        pairMeta.theta(end + 1, 1) = currentTheta; %#ok<AGROW>
        pairMeta.phi(end + 1, 1) = currentPhi; %#ok<AGROW>
        pairMeta.labels{end + 1, 1} = sprintf('T%.0f P%.0f', currentTheta, currentPhi); %#ok<AGROW>
    end
end
end

function [rawMatrix, rawErrMatrix, targetDoseMatrix, compareDoseMatrix, countMatrix] = build_series_matrices_r2015(T, seriesMeta, pairMeta)
nPairs = numel(pairMeta.keys);
nSeries = numel(seriesMeta.keys);
rawMatrix = nan(nPairs, nSeries);
rawErrMatrix = nan(nPairs, nSeries);
targetDoseMatrix = nan(nPairs, nSeries);
compareDoseMatrix = nan(nPairs, nSeries);
countMatrix = zeros(nPairs, nSeries);

rowSeriesKeys = cell(height(T), 1);
rowPairKeys = cell(height(T), 1);
for i = 1:height(T)
    rowSeriesKeys{i} = build_series_key_r2015(T.SourceType{i}, T.Alpha(i));
    rowPairKeys{i} = build_pair_key_r2015(T.THETA(i), T.PHI(i));
end

for p = 1:nPairs
    for s = 1:nSeries
        matchMask = strcmp(rowPairKeys, pairMeta.keys{p}) & strcmp(rowSeriesKeys, seriesMeta.keys{s});
        if ~any(matchMask)
            continue;
        end
        rawVals = T.CompareTarget_pct(matchMask);
        rawVals = rawVals(isfinite(rawVals));
        if isempty(rawVals)
            continue;
        end
        rawMatrix(p, s) = mean(rawVals);

        rawErrVals = T.dCompareTarget_pct(matchMask);
        rawErrVals = rawErrVals(isfinite(rawErrVals));
        if ~isempty(rawErrVals)
            rawErrMatrix(p, s) = mean(rawErrVals);
        end

        targetVals = T.TargetDose_eVg(matchMask);
        targetVals = targetVals(isfinite(targetVals));
        if ~isempty(targetVals)
            targetDoseMatrix(p, s) = mean(targetVals);
        end

        compareVals = T.CompareDose_eVg(matchMask);
        compareVals = compareVals(isfinite(compareVals));
        if ~isempty(compareVals)
            compareDoseMatrix(p, s) = mean(compareVals);
        end

        countMatrix(p, s) = sum(matchMask);
    end
end
end

function [normMatrix, normErrMatrix, denominators] = normalize_series_matrix_r2015(rawMatrix, rawErrMatrix, normalizationMode, normalizedScale)
normMatrix = nan(size(rawMatrix));
normErrMatrix = nan(size(rawErrMatrix));
denominators = nan(1, size(rawMatrix, 2));
modeName = lower(strtrim(normalizationMode));

for s = 1:size(rawMatrix, 2)
    currentVals = rawMatrix(:, s);
    finiteMask = isfinite(currentVals);
    if ~any(finiteMask)
        continue;
    end

    switch modeName
        case 'sum'
            denom = sum(currentVals(finiteMask));
        case 'none'
            denom = 1;
        otherwise
            denom = max(currentVals(finiteMask));
    end

    if ~isfinite(denom) || denom == 0
        continue;
    end
    denominators(s) = denom;
    normMatrix(:, s) = normalizedScale * rawMatrix(:, s) / denom;
    normErrMatrix(:, s) = normalizedScale * rawErrMatrix(:, s) / denom;
end
end

function [availableCount, normMean, normRange, normStd] = compute_pair_statistics_r2015(normMatrix)
nPairs = size(normMatrix, 1);
availableCount = zeros(nPairs, 1);
normMean = nan(nPairs, 1);
normRange = nan(nPairs, 1);
normStd = nan(nPairs, 1);

for i = 1:nPairs
    currentVals = normMatrix(i, :);
    currentVals = currentVals(isfinite(currentVals));
    availableCount(i) = numel(currentVals);
    if isempty(currentVals)
        continue;
    end
    normMean(i) = mean(currentVals);
    normRange(i) = max(currentVals) - min(currentVals);
    if numel(currentVals) > 1
        normStd(i) = std(currentVals);
    else
        normStd(i) = 0;
    end
end
end

function [availableCount, targetMean, targetMax] = compute_target_statistics_r2015(targetDoseMatrix)
nPairs = size(targetDoseMatrix, 1);
availableCount = zeros(nPairs, 1);
targetMean = nan(nPairs, 1);
targetMax = nan(nPairs, 1);

for i = 1:nPairs
    currentVals = targetDoseMatrix(i, :);
    currentVals = currentVals(isfinite(currentVals));
    availableCount(i) = numel(currentVals);
    if isempty(currentVals)
        continue;
    end
    targetMean(i) = mean(currentVals);
    targetMax(i) = max(currentVals);
end
end

function idx = find_reference_series_index_by_alpha_r2015(seriesMeta, alphaValue)
idx = [];
if nargin < 2 || isempty(seriesMeta) || isempty(seriesMeta.alphas)
    return;
end
tol = max(1e-9, abs(alphaValue) * 1e-6);
match = find(abs(seriesMeta.alphas - alphaValue) <= tol);
if ~isempty(match)
    idx = match(1);
end
end

function idx = find_first_finite_series_index_r2015(valueMatrix)
idx = [];
if isempty(valueMatrix)
    return;
end
for s = 1:size(valueMatrix, 2)
    if any(isfinite(valueMatrix(:, s)))
        idx = s;
        return;
    end
end
end

function idx = find_series_indices_by_alpha_r2015(seriesMeta, alphaValues)
idx = [];
if nargin < 2 || isempty(alphaValues) || isempty(seriesMeta) || isempty(seriesMeta.alphas)
    return;
end
for i = 1:numel(alphaValues)
    currentIdx = find_reference_series_index_by_alpha_r2015(seriesMeta, alphaValues(i));
    if ~isempty(currentIdx)
        idx(end + 1) = currentIdx; %#ok<AGROW>
    end
end
idx = unique(idx, 'stable');
end

function pairMetaOut = reorder_pair_metadata_r2015(pairMetaIn, order)
