end
pairMetaOut.theta = pairMetaIn.theta(order);
pairMetaOut.phi = pairMetaIn.phi(order);
pairMetaOut.labels = pairMetaIn.labels(order);
pairMetaOut.keys = pairMetaIn.keys(order);
end

function order = sort_pair_order_r2015(normRange, normMean, thetaValues, phiValues)
sortRange = normRange;
sortMean = normMean;
sortRange(~isfinite(sortRange)) = -inf;
sortMean(~isfinite(sortMean)) = -inf;

sortMatrix = [ ...
    -sortRange(:), ...
    -sortMean(:), ...
    thetaValues(:), ...
    phiValues(:), ...
    (1:numel(thetaValues))' ...
];
sorted = sortrows(sortMatrix, [1 2 3 4]);
order = sorted(:, 5);
end

function order = sort_pair_order_by_reference_alpha_r2015(normMatrix, refIdx, fallbackMean, thetaValues, phiValues)
refVals = normMatrix(:, refIdx);
refSortVals = refVals;
refSortVals(~isfinite(refSortVals)) = -inf;
meanSortVals = fallbackMean;
meanSortVals(~isfinite(meanSortVals)) = -inf;

sortMatrix = [ ...
    -refSortVals(:), ...
    -meanSortVals(:), ...
    thetaValues(:), ...
    phiValues(:), ...
    (1:numel(thetaValues))' ...
];
sorted = sortrows(sortMatrix, [1 2 3 4]);
order = sorted(:, 5);
end

function order = sort_target_pair_order_r2015(targetMean, targetMax, thetaValues, phiValues)
