sortMax = targetMax;
sortMean(~isfinite(sortMean)) = -inf;
sortMax(~isfinite(sortMax)) = -inf;

sortMatrix = [ ...
    -sortMean(:), ...
    -sortMax(:), ...
    thetaValues(:), ...
    phiValues(:), ...
    (1:numel(thetaValues))' ...
];
sorted = sortrows(sortMatrix, [1 2 3 4]);
order = sorted(:, 5);
end

function longTable = build_long_output_table_r2015(group, pairMeta, seriesMeta, rawMatrix, rawErrMatrix, targetDoseMatrix, compareDoseMatrix, normMatrix, normErrMatrix, countMatrix, seriesDenominator)
