seriesLabelCol = cell(nRows, 1);
sourceTypeCol = cell(nRows, 1);
alphaCol = nan(nRows, 1);
rawPctCol = nan(nRows, 1);
dRawPctCol = nan(nRows, 1);
targetDoseCol = nan(nRows, 1);
compareDoseCol = nan(nRows, 1);
