function matrixTable = build_matrix_output_table_r2015(pairMeta, seriesMeta, rawMatrix, rawErrMatrix, targetDoseMatrix, compareDoseMatrix, normMatrix, normErrMatrix, countMatrix, availableCount, normMean, normRange, normStd)
