function summaryTable = build_series_summary_table_r2015(seriesMeta, rawMatrix, countMatrix, seriesDenominator)
nSeries = numel(seriesMeta.labels);
sourceTypeCol = cell(nSeries, 1);
seriesLabelCol = cell(nSeries, 1);
alphaCol = nan(nSeries, 1);
nPairsCol = zeros(nSeries, 1);
rawMinCol = nan(nSeries, 1);
rawMaxCol = nan(nSeries, 1);
rawMeanCol = nan(nSeries, 1);
denomCol = nan(nSeries, 1);
