for s = 1:nSeries
    vals = rawMatrix(:, s);
    vals = vals(isfinite(vals));
    sourceTypeCol{s} = seriesMeta.sourceTypes{s};
    seriesLabelCol{s} = seriesMeta.labels{s};
    alphaCol(s) = seriesMeta.alphas(s);
    nPairsCol(s) = numel(vals);
    if ~isempty(vals)
        rawMinCol(s) = min(vals);
        rawMaxCol(s) = max(vals);
        rawMeanCol(s) = mean(vals);
    end
    denomCol(s) = seriesDenominator(s);
    countCol(s) = sum(countMatrix(:, s));
end

summaryTable = table(sourceTypeCol, seriesLabelCol, alphaCol, nPairsCol, rawMinCol, rawMaxCol, rawMeanCol, denomCol, countCol, ...
    'VariableNames', {'SourceType', 'SeriesLabel', 'Alpha', 'NAnglePairs', 'RawMin_pct', 'RawMax_pct', 'RawMean_pct', 'NormalizationDenominator', 'NContributingRows'});
