function screeningTable = build_screening_table_r2015(pairMeta, seriesMeta, rawMatrix, targetDoseMatrix, ratioOrderAll, targetPairOrder, subsetSeriesIdx, subsetRefIdx)
nPairs = numel(pairMeta.labels);
ratioMean = nanmean_compat_r2015(rawMatrix, 2);
targetDoseMean = nanmean_compat_r2015(targetDoseMatrix, 2);
ratioMin = nanmin_compat_r2015(rawMatrix, 2);
ratioMax = nanmax_compat_r2015(rawMatrix, 2);
targetDoseMin = nanmin_compat_r2015(targetDoseMatrix, 2);
targetDoseMax = nanmax_compat_r2015(targetDoseMatrix, 2);

screeningTable = table(pairMeta.labels, pairMeta.theta, pairMeta.phi, ratioMean, ratioMin, ratioMax, targetDoseMean, targetDoseMin, targetDoseMax, ...
    'VariableNames', {'AnglePair', 'THETA', 'PHI', 'RatioMean_pct', 'RatioMin_pct', 'RatioMax_pct', 'TargetDoseMean_eVg', 'TargetDoseMin_eVg', 'TargetDoseMax_eVg'});

screeningTable.OrderRefAlpha2p86 = build_rank_vector_r2015(ratioOrderAll, nPairs);
screeningTable.OrderTargetDoseDesc = build_rank_vector_r2015(targetPairOrder, nPairs);

