    dim = 1;
end
if dim ~= 2
    error('nanmean_compat_r2015 currently supports dim = 2 only.');
end
vals = nan(size(M, 1), 1);
for i = 1:size(M, 1)
    row = M(i, :);
    row = row(isfinite(row));
    if ~isempty(row)
        vals(i) = mean(row);
    end
end
end

