function plotCombined = resolve_plot_titles_r2015(group, seriesMeta, refAllIdx, subsetRefIdx, rawRatioSubsetAlphas, grau)
plotCombined = struct();

if nargin < 3 || isempty(refAllIdx) || refAllIdx < 1 || refAllIdx > numel(seriesMeta.labels)
    refAllLabel = ['alpha = ' strrep(num2str(2.86), '.', ',') grau];
