    refAllLabel = seriesMeta.labels{refAllIdx};
end

if nargin < 4 || isempty(subsetRefIdx) || subsetRefIdx < 1 || subsetRefIdx > numel(seriesMeta.labels)
    refSubsetLabel = ['alpha = ' strrep(num2str(1), '.', ',') grau];
else
    refSubsetLabel = seriesMeta.labels{subsetRefIdx};
end

