defaultRatioSubsetTitle = sprintf('Comparacao bruta por angulo: %s / %s | %s | ordem definida por %s', group.compareLabel, group.targetLabel, subsetAlphaText, refSubsetLabel);
defaultDoseRankedTitle = sprintf('Dose depositada em %s por par angular | ordem por dose media no alvo', group.targetLabel);
defaultDoseRatioOrderTitle = sprintf('Dose depositada em %s por par angular | ordem do grafico da razao (%s)', group.targetLabel, refAllLabel);
defaultScatterTitle = sprintf('Dispersao: dose em %s vs %s / %s', group.targetLabel, group.compareLabel, group.targetLabel);

try
    answers = prompt_plot_titles_dialog_r2015( ...
        {'Title for all-alpha raw ratio plot', ...
         'Title for subset raw ratio plot', ...
         'Title for target dose descending plot', ...
         'Title for target dose ratio-order plot', ...
