    plotCombined.ratioSubsetTitle = strtrim(answers{2});
    plotCombined.doseRankedTitle = strtrim(answers{3});
    plotCombined.doseRatioOrderTitle = strtrim(answers{4});
    plotCombined.scatterTitle = strtrim(answers{5});
