    if isempty(plotCombined.doseRatioOrderTitle)
        plotCombined.doseRatioOrderTitle = defaultDoseRatioOrderTitle;
    end
    if isempty(plotCombined.scatterTitle)
        plotCombined.scatterTitle = defaultScatterTitle;
    end
end
end

function answers = prompt_plot_titles_dialog_r2015(promptList, dialogTitle, defaultValues)
answers = {};
if nargin < 1 || isempty(promptList)
    return;
end
if nargin < 2 || isempty(dialogTitle)
    dialogTitle = 'Edit plot titles';
end
if nargin < 3 || isempty(defaultValues)
    defaultValues = cell(size(promptList));
end

nItems = numel(promptList);
dlgWidth = 1220;
rowHeight = 76;
dlgHeight = max(260, 120 + nItems * rowHeight);
dlg = dialog('Name', dialogTitle, ...
    'Units', 'pixels', ...
    'Position', [120 80 dlgWidth dlgHeight], ...
    'Resize', 'on', ...
    'WindowStyle', 'normal', ...
    'Visible', 'off');

editHandles = zeros(nItems, 1);
for i = 1:nItems
    yBase = dlgHeight - 38 - i * rowHeight;
    uicontrol('Parent', dlg, ...
        'Style', 'text', ...
        'String', promptList{i}, ...
        'Units', 'pixels', ...
        'Position', [22 yBase + 34 dlgWidth - 44 20], ...
        'HorizontalAlignment', 'left');
    editHandles(i) = uicontrol('Parent', dlg, ...
        'Style', 'edit', ...
        'String', defaultValues{i}, ...
        'Units', 'pixels', ...
        'Position', [22 yBase dlgWidth - 44 28], ...
        'HorizontalAlignment', 'left', ...
        'BackgroundColor', 'white');
end

uicontrol('Parent', dlg, ...
    'Style', 'pushbutton', ...
    'String', 'OK', ...
    'Units', 'pixels', ...
    'Position', [dlgWidth - 208 18 82 30], ...
    'Callback', @confirm_dialog_r2015);
uicontrol('Parent', dlg, ...
    'Style', 'pushbutton', ...
    'String', 'Cancel', ...
    'Units', 'pixels', ...
    'Position', [dlgWidth - 112 18 82 30], ...
    'Callback', @cancel_dialog_r2015);

set(dlg, 'CloseRequestFcn', @cancel_dialog_r2015);
movegui(dlg, 'center');
set(dlg, 'Visible', 'on');
uiwait(dlg);

if ishandle(dlg)
    storedAnswers = getappdata(dlg, 'angle_ranking_plot_title_answers');
    if ~isempty(storedAnswers)
        answers = storedAnswers;
    end
    delete(dlg);
end

    function confirm_dialog_r2015(varargin)
        localAnswers = cell(nItems, 1);
        for j = 1:nItems
            localAnswers{j} = get(editHandles(j), 'String');
        end
        setappdata(dlg, 'angle_ranking_plot_title_answers', localAnswers);
        uiresume(dlg);
    end

    function cancel_dialog_r2015(varargin)
        uiresume(dlg);
    end
end

function plot_raw_ratio_horizontal_dots_r2015(group, pairLabels, seriesLabels, rawMatrix, rawErrMatrix, seriesIdx, outDir, baseName, plotTitle)
