colors = lines(numel(seriesLabels));
markerList = {'o', 's', 'd', '^', 'v', '>', '<', 'p', 'h', 'x', '+'};
offsets = compute_series_offsets_r2015(nShownSeries, 0.66);
plotHandles = [];
plotLegendLabels = {};
xMax = 0;

for k = 1:nShownSeries
    s = seriesIdx(k);
    currentVals = rawMatrix(:, s);
    currentErrs = rawErrMatrix(:, s);
    currentVals = currentVals(:);
    currentErrs = currentErrs(:);
    finiteMask = isfinite(currentVals);
    if ~any(finiteMask)
        continue;
    end

    yVals = (1:nPairs)' + offsets(k);
    yVals = yVals(:);
    markerValue = markerList{mod(k - 1, numel(markerList)) + 1};
    colorValue = colors(s, :);

    try
        errorMask = finiteMask & isfinite(currentErrs) & currentErrs > 0;
        errorRows = find(errorMask);
        for e = 1:numel(errorRows)
            rowIdx = errorRows(e);
            line( ...
                'Parent', ax, ...
                'XData', [currentVals(rowIdx) - currentErrs(rowIdx), currentVals(rowIdx) + currentErrs(rowIdx)], ...
                'YData', [yVals(rowIdx), yVals(rowIdx)], ...
                'Color', [0.25 0.25 0.25], ...
                'LineWidth', 0.8);
        end
    catch ME
        error('Error-bar stage failed for %s: %s', seriesLabels{s}, ME.message);
    end

    xPlot = currentVals(finiteMask);
    yPlot = yVals(finiteMask);
    xPlot = xPlot(:);
    yPlot = yPlot(:);
    if numel(xPlot) ~= numel(yPlot)
        error('Point-stage length mismatch for %s: x=%d, y=%d', seriesLabels{s}, numel(xPlot), numel(yPlot));
    end
    try
        h = line( ...
            'Parent', ax, ...
            'XData', xPlot(:)', ...
            'YData', yPlot(:)', ...
            'LineStyle', 'none', ...
            'Marker', markerValue, ...
            'MarkerSize', 7, ...
            'MarkerFaceColor', colorValue, ...
            'MarkerEdgeColor', [0.1 0.1 0.1], ...
            'DisplayName', seriesLabels{s});
    catch ME
        error('Point-stage failed for %s: %s', seriesLabels{s}, ME.message);
    end
    plotHandles(end + 1) = h; %#ok<AGROW>
    plotLegendLabels{end + 1, 1} = seriesLabels{s}; %#ok<AGROW>

    finiteVals = currentVals(finiteMask);
    finiteErrs = currentErrs(finiteMask);
    finiteErrs(~isfinite(finiteErrs)) = 0;
    xMax = max(xMax, max(finiteVals + finiteErrs));
end

hold(ax, 'off');

if isempty(plotHandles)
    close(fig);
    return;
end

try
    set(ax, 'YTick', 1:nPairs, 'YTickLabel', pairLabels, 'YDir', 'reverse', 'FontSize', 12);
catch ME
    error('Axis-label stage failed: nPairs=%d, nLabels=%d, %s', nPairs, numel(pairLabels), ME.message);
end
ylim(ax, [0.5, nPairs + 0.5]);
xlim(ax, [0, max(1, 1.05 * xMax)]);
grid(ax, 'on');
box(ax, 'on');
xlabel(ax, sprintf('%s / %s (%%)', group.compareLabel, group.targetLabel), 'FontSize', 13);
ylabel(ax, 'Theta/Phi pair', 'FontSize', 13);
title(ax, plotTitle, 'Interpreter', 'none', 'FontSize', 16, 'FontWeight', 'bold');
try
    legend(ax, plotHandles, plotLegendLabels, 'Location', 'EastOutside', 'Interpreter', 'none', 'FontSize', 12);
catch ME
    error('Legend stage failed: handles=%d, labels=%d, %s', numel(plotHandles), numel(plotLegendLabels), ME.message);
end
set(fig, 'PaperPositionMode', 'auto');
saveas(fig, fullfile(outDir, [baseName '.png']));
close(fig);
end

function offsets = compute_series_offsets_r2015(nSeries, totalSpread)
if nargin < 2 || ~isfinite(totalSpread) || totalSpread <= 0
    totalSpread = 0.66;
end
if nargin < 1 || isempty(nSeries) || nSeries <= 1
    offsets = 0;
    return;
end
offsets = linspace(-totalSpread / 2, totalSpread / 2, nSeries);
offsets = offsets(:)';
end

