function [compareToken, targetToken] = parse_ranking_group_tokens_r2015(pathValue)
compareToken = '';
targetToken = '';
[~, fileName, fileExt] = fileparts(pathValue);
cleanName = regexprep(fileName, '\s+\(\d+\)$', '');
match = regexp([cleanName fileExt], '^angle_ranking_(.+)_vs_(.+)\.csv$', 'tokens', 'once');
if isempty(match)
    return;
end
compareToken = match{1};
targetToken = match{2};
end

function name = display_label_from_token_r2015(token)
if nargin < 1 || isempty(token)
    name = '';
    return;
end
key = normalize_body_compare_key_r2015(token);
switch key
    case 'olhodireito'
        name = 'Olho direito';
    case 'olhoesquerdo'
        name = 'Olho esquerdo';
    case 'tumorolhodto'
        name = 'Tumor olho dto';
    case 'tumorouvidoesq'
        name = 'Tumor ouvido esq';
    case 'cerebro'
        name = 'Cerebro';
    otherwise
        name = strrep(token, '_', ' ');
end
end

function key = build_series_key_r2015(sourceType, alphaValue)
key = [safe_file_token_r2015(sourceType) '|' alpha_token_r2015(alphaValue)];
end

function key = build_pair_key_r2015(thetaValue, phiValue)
key = sprintf('T%.12g_P%.12g', thetaValue, phiValue);
end

function token = alpha_token_r2015(alphaValue)
if ~isfinite(alphaValue)
    token = 'nan';
    return;
end
token = num2str(alphaValue, '%.12g');
token = strrep(token, '.', 'p');
token = strrep(token, '-', 'm');
end

function T = load_dose_sheet_r2015(excelPath)
[~, ~, raw] = xlsread(excelPath, 'Dose');
if isempty(raw) || size(raw, 1) < 2
    error('Dose sheet is empty or missing usable rows.');
end

headers = raw(1, :);
rows = raw(2:end, :);

caseIdx = find_header_index_r2015(headers, {'Case'});
sourceTypeIdx = find_optional_header_index_r2015(headers, {'Spectrum Type', 'Source Type', 'SourceType'});
componentIdx = find_header_index_r2015(headers, {'Component'});
edepIdx = find_header_index_r2015(headers, {'Edep (eV)', 'Edep_eV'});
dedepIdx = find_header_index_r2015(headers, {'dE (eV)', 'dE_eV'});
doseEvgIdx = find_header_index_r2015(headers, {'Dose (eV/g)', 'Dose_eV_g'});
ddoseEvgIdx = find_header_index_r2015(headers, {'dDose (eV/g)', 'dDose_eV_g'});
doseGyIdx = find_optional_header_index_r2015(headers, {'Dose (Gy)', 'Dose_Gy'});
ddoseGyIdx = find_optional_header_index_r2015(headers, {'dDose (Gy)', 'dDose_Gy'});

T.case_names = cell_column_to_strings_r2015(rows(:, caseIdx));
if ~isnan(sourceTypeIdx)
    T.source_types = cell_column_to_strings_r2015(rows(:, sourceTypeIdx));
else
    T.source_types = repmat({''}, size(rows, 1), 1);
end
for i = 1:numel(T.source_types)
    T.source_types{i} = normalize_source_type_label_r2015(T.source_types{i});
end
T.component_names = cell_column_to_strings_r2015(rows(:, componentIdx));
T.edep_ev = cell_column_to_numeric_r2015(rows(:, edepIdx));
T.dedep_ev = cell_column_to_numeric_r2015(rows(:, dedepIdx));
T.dose_evg = cell_column_to_numeric_r2015(rows(:, doseEvgIdx));
T.ddose_evg = cell_column_to_numeric_r2015(rows(:, ddoseEvgIdx));
T.dose_gy = cell_column_to_numeric_r2015_by_index_r2015(rows, doseGyIdx);
T.ddose_gy = cell_column_to_numeric_r2015_by_index_r2015(rows, ddoseGyIdx);

keep = ~cellfun(@isempty, T.case_names) & ~cellfun(@isempty, T.component_names);
T.case_names = T.case_names(keep);
T.source_types = T.source_types(keep);
T.component_names = T.component_names(keep);
T.edep_ev = T.edep_ev(keep);
T.dedep_ev = T.dedep_ev(keep);
T.dose_evg = T.dose_evg(keep);
T.ddose_evg = T.ddose_evg(keep);
T.dose_gy = T.dose_gy(keep);
T.ddose_gy = T.ddose_gy(keep);
end

function idx = find_header_index_r2015(headers, candidates)
idx = [];
for i = 1:numel(headers)
    current = normalize_header_name_r2015(headers{i});
    for j = 1:numel(candidates)
        if strcmp(current, normalize_header_name_r2015(candidates{j}))
            idx = i;
            return;
        end
    end
end
error('Could not find expected Excel column header: ''%s''.', candidates{1});
end

function idx = find_optional_header_index_r2015(headers, candidates)
idx = NaN;
for i = 1:numel(headers)
    current = normalize_header_name_r2015(headers{i});
    for j = 1:numel(candidates)
        if strcmp(current, normalize_header_name_r2015(candidates{j}))
            idx = i;
            return;
        end
    end
end
end

function out = normalize_header_name_r2015(value)
if isnumeric(value)
    value = num2str(value);
elseif ~ischar(value)
    value = '';
end
out = regexprep(lower(strtrim(value)), '[^a-z0-9]+', '');
end

function values = cell_column_to_strings_r2015(col)
values = cell(size(col));
for i = 1:numel(col)
    if ischar(col{i})
        values{i} = strtrim(col{i});
    elseif isnumeric(col{i}) && isscalar(col{i}) && ~isnan(col{i})
        values{i} = num2str(col{i});
    else
        values{i} = '';
    end
end
values = values(:);
end

function values = cell_column_to_numeric_r2015(col)
values = nan(size(col));
for i = 1:numel(col)
    if isnumeric(col{i}) && isscalar(col{i})
        values(i) = col{i};
    elseif ischar(col{i})
        values(i) = str2double(strrep(col{i}, ',', '.'));
    end
end
values = values(:);
end

function values = cell_column_to_numeric_r2015_by_index_r2015(rows, idx)
if isnan(idx)
    values = nan(size(rows, 1), 1);
else
    values = cell_column_to_numeric_r2015(rows(:, idx));
end
end

function mask = build_component_match_mask_r2015(componentNames, desiredNames)
mask = false(numel(componentNames), 1);
desiredNames = normalize_body_name_list_r2015(desiredNames);
if isempty(desiredNames)
    return;
end
desiredKeys = cell(size(desiredNames));
for j = 1:numel(desiredNames)
    desiredKeys{j} = normalize_body_compare_key_r2015(desiredNames{j});
end
for i = 1:numel(componentNames)
    current = '';
    if ischar(componentNames{i})
        current = strtrim(componentNames{i});
    end
    currentKey = normalize_body_compare_key_r2015(current);
    for j = 1:numel(desiredKeys)
        if strcmp(currentKey, desiredKeys{j})
            mask(i) = true;
            break;
        end
    end
end
end

function names = normalize_body_name_list_r2015(rawNames)
names = {};
if nargin < 1 || isempty(rawNames)
    return;
end
if ischar(rawNames)
    rawNames = {rawNames};
elseif ~iscell(rawNames)
    return;
end
for i = 1:numel(rawNames)
    item = rawNames{i};
    label = '';
    if ischar(item)
        label = strtrim(item);
    elseif iscell(item) && ~isempty(item) && ischar(item{1})
        label = strtrim(item{1});
    end
    if isempty(label)
        continue;
    end
    labelKey = normalize_body_compare_key_r2015(label);
    if isempty(labelKey)
        continue;
    end
    duplicate = false;
    for j = 1:numel(names)
        if strcmp(normalize_body_compare_key_r2015(names{j}), labelKey)
            duplicate = true;
            break;
        end
    end
    if ~duplicate
        names{end + 1, 1} = label; %#ok<AGROW>
    end
end
end

function key = normalize_body_compare_key_r2015(value)
if nargin < 1 || isempty(value)
    key = '';
    return;
end
if isnumeric(value)
    value = num2str(value);
elseif ~ischar(value)
    try
        value = char(value);
    catch
        value = '';
    end
end
value = strip_portuguese_diacritics_r2015(strtrim(value));
key = regexprep(lower(value), '[^a-z0-9]+', '');
switch key
    case 'crebro'
        key = 'cerebro';
    case 'olhodto'
        key = 'olhodireito';
    case 'olhoesq'
        key = 'olhoesquerdo';
end
end

function out = strip_portuguese_diacritics_r2015(value)
out = char(value);
replacements = {
    char(193), 'A'; char(192), 'A'; char(195), 'A'; char(194), 'A'; char(196), 'A';
    char(225), 'a'; char(224), 'a'; char(227), 'a'; char(226), 'a'; char(228), 'a';
    char(201), 'E'; char(200), 'E'; char(202), 'E'; char(203), 'E';
    char(233), 'e'; char(232), 'e'; char(234), 'e'; char(235), 'e';
    char(205), 'I'; char(204), 'I'; char(206), 'I'; char(207), 'I';
    char(237), 'i'; char(236), 'i'; char(238), 'i'; char(239), 'i';
    char(211), 'O'; char(210), 'O'; char(213), 'O'; char(212), 'O'; char(214), 'O';
    char(243), 'o'; char(242), 'o'; char(245), 'o'; char(244), 'o'; char(246), 'o';
    char(218), 'U'; char(217), 'U'; char(219), 'U'; char(220), 'U';
    char(250), 'u'; char(249), 'u'; char(251), 'u'; char(252), 'u';
    char(199), 'C'; char(231), 'c'
};
for i = 1:size(replacements, 1)
    out = strrep(out, replacements{i, 1}, replacements{i, 2});
end
end

function labels = fill_empty_labels_r2015(labels, fallbackLabel)
labels = labels(:);
for i = 1:numel(labels)
    current = '';
    if ischar(labels{i})
        current = strtrim(labels{i});
    end
    if isempty(current)
        labels{i} = fallbackLabel;
    end
end
end

function out = display_source_type_r2015(label)
out = normalize_source_type_label_r2015(label);
if isempty(out)
    out = 'Unknown source';
end
end

function out = normalize_source_type_label_r2015(label)
if nargin < 1 || isempty(label)
    out = '';
    return;
end
if isnumeric(label)
    label = num2str(label);
elseif ~ischar(label)
    try
        label = char(label);
    catch
        label = '';
    end
end
text = strtrim(label);
text = strip_portuguese_diacritics_r2015(text);
text = regexprep(text, '[_]+', ' ');
text = regexprep(text, '\s+', ' ');
key = regexprep(lower(text), '[^a-z0-9]+', '');
switch key
    case 'linac6mev'
        out = 'LINAC 6MeV';
    case {'cobalt60source', 'cobalt60', 'co60', 'co60source'}
        out = 'Cobalt-60 source';
    otherwise
        out = text;
end
end

function token = safe_file_token_r2015(label)
token = regexprep(lower(display_source_type_r2015(label)), '[^a-z0-9]+', '_');
token = regexprep(token, '_+', '_');
token = regexprep(token, '^_|_$', '');
if isempty(token)
    token = 'unknown_source';
end
end

function token = safe_label_file_token_r2015(label)
if nargin < 1 || isempty(label)
    token = 'label';
    return;
end
if isnumeric(label)
    label = num2str(label);
elseif ~ischar(label)
    try
        label = char(label);
    catch
        label = '';
    end
end
key = normalize_body_compare_key_r2015(label);
switch key
    case 'olhodireito'
        token = 'olho_direito';
    case 'olhoesquerdo'
        token = 'olho_esquerdo';
    case 'tumorolhodto'
        token = 'tumor_olho_dto';
    case 'tumorouvidoesq'
        token = 'tumor_ouvido_esq';
    case 'cerebro'
        token = 'cerebro';
    otherwise
        text = strip_portuguese_diacritics_r2015(strtrim(label));
        token = regexprep(lower(text), '[^a-z0-9]+', '_');
        token = regexprep(token, '_+', '_');
        token = regexprep(token, '^_|_$', '');
        if isempty(token)
            token = 'label';
        end
end
end

function [ratioPct, dRatioPct] = safe_ratio_pct_r2015(numeratorDose, dNumeratorDose, denominatorDose, dDenominatorDose)
ratioPct = NaN;
dRatioPct = NaN;
if ~isfinite(numeratorDose) || ~isfinite(denominatorDose)
    return;
end
if numeratorDose <= 0 || denominatorDose <= 0
    return;
end
ratioPct = 100 * numeratorDose / denominatorDose;
if ~isfinite(dNumeratorDose) || ~isfinite(dDenominatorDose)
    return;
end
if dNumeratorDose < 0 || dDenominatorDose < 0
    return;
end
dRatioPct = abs(ratioPct) * sqrt((dNumeratorDose / numeratorDose)^2 + (dDenominatorDose / denominatorDose)^2);
if ~isfinite(dRatioPct)
    dRatioPct = NaN;
end
end

function varName = find_table_var_name_r2015(T, candidates)
varName = '';
vars = T.Properties.VariableNames;
for i = 1:numel(vars)
    current = normalize_header_name_r2015(vars{i});
    for j = 1:numel(candidates)
        if strcmp(current, normalize_header_name_r2015(candidates{j}))
            varName = vars{i};
            return;
        end
    end
end
error('Could not find expected table column: ''%s''.', candidates{1});
end

function varName = find_optional_table_var_name_r2015(T, candidates)
varName = '';
vars = T.Properties.VariableNames;
for i = 1:numel(vars)
    current = normalize_header_name_r2015(vars{i});
    for j = 1:numel(candidates)
        if strcmp(current, normalize_header_name_r2015(candidates{j}))
            varName = vars{i};
            return;
        end
    end
end
end

function values = table_column_to_strings_r2015(T, varName)
if isempty(varName)
    values = repmat({''}, height(T), 1);
    return;
end
raw = T.(varName);
values = cell(height(T), 1);
for i = 1:height(T)
    if iscell(raw)
        current = raw{i};
    else
        current = raw(i);
    end
    if ischar(current)
        values{i} = strtrim(current);
    elseif isnumeric(current) && isscalar(current) && ~isnan(current)
        values{i} = num2str(current);
    else
        values{i} = '';
    end
end
end

function values = table_column_to_numeric_r2015(T, varName)
if isempty(varName)
    values = nan(height(T), 1);
    return;
end
raw = T.(varName);
values = nan(height(T), 1);
for i = 1:height(T)
    if iscell(raw)
        current = raw{i};
    else
        current = raw(i);
    end
    if isnumeric(current) && isscalar(current)
        values(i) = current;
    elseif ischar(current)
        values(i) = str2double(strrep(current, ',', '.'));
    end
end
end

function out = make_valid_var_name_r2015(label)
out = regexprep(lower(strtrim(label)), '[^a-z0-9]+', '_');
out = regexprep(out, '_+', '_');
out = regexprep(out, '^_|_$', '');
if isempty(out)
    out = 'value';
end
if ~isempty(regexp(out(1), '[0-9]', 'once'))
    out = ['x_' out];
end
end
